"""Bring up robot_state_publisher, ros2_control, and MoveIt move_group for simple_arm.

This launch file loads all files directly from paths on disk (urdf/, config/)
so no colcon-built ROS package is required.
"""
import os
import yaml

from launch import LaunchDescription
from launch.actions import ExecuteProcess
from launch_ros.actions import Node

HERE = os.path.dirname(os.path.abspath(__file__))
BASE = os.path.dirname(HERE)


def load_file(path):
    with open(path, "r") as f:
        return f.read()


def load_yaml(path):
    with open(path, "r") as f:
        return yaml.safe_load(f)


def generate_launch_description():
    urdf_path = os.path.join(BASE, "urdf", "arm.urdf")
    srdf_path = os.path.join(BASE, "config", "arm.srdf")

    robot_description = {"robot_description": load_file(urdf_path)}
    robot_description_semantic = {"robot_description_semantic": load_file(srdf_path)}

    robot_description_kinematics = {
        "robot_description_kinematics": load_yaml(
            os.path.join(BASE, "config", "kinematics.yaml")
        )
    }

    ompl_yaml = load_yaml(os.path.join(BASE, "config", "ompl_planning.yaml"))
    planning_pipelines = {
        "planning_pipelines": ["ompl"],
        "default_planning_pipeline": "ompl",
        "ompl": ompl_yaml,
    }

    robot_description_planning = {
        "robot_description_planning": load_yaml(
            os.path.join(BASE, "config", "joint_limits.yaml")
        )
    }

    moveit_controllers = load_yaml(os.path.join(BASE, "config", "moveit_controllers.yaml"))
    trajectory_execution = {
        "moveit_manage_controllers": True,
    }
    trajectory_execution.update(moveit_controllers)

    planning_scene_monitor_config = {
        "publish_planning_scene": True,
        "publish_geometry_updates": True,
        "publish_state_updates": True,
        "publish_transforms_updates": True,
        "publish_robot_description_semantic": True,
    }

    move_group_extra = {
        "allow_trajectory_execution": True,
        "capabilities": "",
        "disable_capabilities": "",
        "monitor_dynamics": False,
    }

    ros2_controllers_path = os.path.join(BASE, "config", "ros2_controllers.yaml")

    nodes = []

    # robot_state_publisher: publishes TF from joint_states + URDF
    nodes.append(
        Node(
            package="robot_state_publisher",
            executable="robot_state_publisher",
            output="screen",
            parameters=[robot_description, {"publish_frequency": 30.0}],
        )
    )

    # ros2_control_node: controller_manager with mock hardware
    nodes.append(
        Node(
            package="controller_manager",
            executable="ros2_control_node",
            output="screen",
            parameters=[robot_description, ros2_controllers_path],
        )
    )

    # spawn controllers once controller_manager is up
    nodes.append(
        ExecuteProcess(
            cmd=[
                "ros2", "run", "controller_manager", "spawner",
                "joint_state_broadcaster",
            ],
            output="screen",
        )
    )
    nodes.append(
        ExecuteProcess(
            cmd=[
                "ros2", "run", "controller_manager", "spawner",
                "arm_controller",
            ],
            output="screen",
        )
    )

    # move_group: the core MoveIt node
    move_group_params = [
        robot_description,
        robot_description_semantic,
        robot_description_kinematics,
        planning_pipelines,
        robot_description_planning,
        trajectory_execution,
        planning_scene_monitor_config,
        move_group_extra,
    ]
    nodes.append(
        Node(
            package="moveit_ros_move_group",
            executable="move_group",
            output="screen",
            parameters=move_group_params,
        )
    )

    return LaunchDescription(nodes)

